+  const remoteSha = await fetchRemoteSha();
+  const local = await readLocalMeta();
+  const localCount = await countCsv(MIDI_DIR);
+
+  if (!force && local?.sha === remoteSha && localCount > 0) {
+    return {
+      ok: true,
+      updated: false,
+      sha: remoteSha,
+      count: localCount,
+      message: "Already up to date",
+    };
